import React, { useContext } from "react";
import ProductContext from "./store2/product-context";

import "./AddProduct.css";
import CartContext from "../store/cart-context";
const AddProduct = () => {
  const { openProduct, selectedItem } = useContext(ProductContext);
  const { addItems } = useContext(CartContext);

  //console.log("from addProduct" ,selectedItem);

  // const addToCart = (size, name, price) => {
  //   if (selectedItem) {
  //     console.log("Selected item:", selectedItem);
  //     const item = {
  //       id: selectedItem.id,
  //       name: name,
  //       price: price,
  //       size: size,
  //       amount: 1, // Set amount to 1
  //     };
  //     addItems(item); // Call addItems function from CartContext
  //   }
  // };
  const addToCart = (size) => {
    if (selectedItem && selectedItem.length > 0) {
      const item = {
        id: selectedItem[0].id,
        name: selectedItem[0].name,
        price: selectedItem[0].price,
        size: size,
        amount: 1, // Set amount to 1
      };
      addItems(item); // Call addItems function from CartContext
    }
  };
  return (
    <div>
      {openProduct && selectedItem && (
        <div className="addProduct">
          {selectedItem.map((item) => (
            <div key={item.id}>
              <h2>{item.name}</h2>
              <p>Description: {item.description}</p>
              <p>Price: Rs {item.price}</p>
              <button
                onClick={() =>
                  addToCart(
                    "Large",
                    selectedItem[0].name,
                    selectedItem[0].price
                  )
                }
              >
                Buy Large {item.large}
              </button>
              <button
                onClick={() =>
                  addToCart(
                    "Medium",
                    selectedItem[0].name,
                    selectedItem[0].price
                  )
                }
              >
                Buy Medium {item.medium}
              </button>
              <button
                onClick={() =>
                  addToCart(
                    "Small",
                    selectedItem[0].name,
                    selectedItem[0].price
                  )
                }
              >
                Buy Small {item.small}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default AddProduct;
